import {validCurve} from '../animation/curves.js';
import {validate as structure,animatable} from './model.js';
const color=v=>typeof v==='string'&&/^(#[0-9a-f]{3,8}|none|transparent)$/i.test(v);
function nodes(value){if(!Array.isArray(value)||value.length>20000)throw Error('Invalid path geometry.');for(const p of value){if(p.bevelRadius!==undefined&&(!Number.isFinite(p.bevelRadius)||p.bevelRadius<0||p.bevelRadius>4096)||p.bevelStyle!==undefined&&!['round','bevel'].includes(p.bevelStyle))throw Error('Invalid point bevel.');for(const pt of [p,p.in,p.out].filter(Boolean))if(!Number.isFinite(pt.x)||!Number.isFinite(pt.y))throw Error('Invalid path node.');}}
const validId=v=>typeof v==='string'&&/^[A-Za-z0-9_-]{1,100}$/.test(v);
export function validate(p){structure(p);if(p.playback){const t=p.playback;if(![t.start,t.end,t.bpm,t.beatsPerBar].every(Number.isFinite)||t.start<0||t.end<=t.start||t.end>p.duration+.00001||t.bpm<20||t.bpm>300||!Number.isInteger(t.beatsPerBar)||t.beatsPerBar<1||t.beatsPerBar>16)throw Error('Invalid playback loop.');}if(!validId(p.id))throw Error('Invalid project ID.');if(typeof p.name!=='string'||!color(p.background))throw Error('Invalid project metadata.');const visit=list=>list.forEach(n=>{if(!validId(n.id))throw Error('Invalid object ID.');if(n.prefix&&(!Array.isArray(n.prefix)||n.prefix.length!==6||n.prefix.some(v=>!Number.isFinite(v))))throw Error('Invalid transform matrix.');if(!color(n.fill)||!color(n.stroke)||n.width<0||n.height<0)throw Error('Invalid artwork styling.');for(const [key,values] of Object.entries({lineStyle:['solid','dashed','dotted'],strokeProfile:['uniform','taper-both','taper-start','taper-end','brush'],lineCap:['round','butt','square'],lineJoin:['round','miter','bevel']}))if(n[key]!==undefined&&!values.includes(n[key]))throw Error('Invalid line styling.');nodes(n.nodes||[]);if(n.shadowEnabled!==undefined&&typeof n.shadowEnabled!=='boolean')throw Error('Invalid shadow enable state.');for(const p of ['shadowX','shadowY','shadowBlur','shadowOpacity'])if(n[p]!==undefined&&!Number.isFinite(n[p]))throw Error('Invalid shadow value.');if(n.shadowBlur!==undefined&&(n.shadowBlur<0||n.shadowBlur>200)||n.shadowOpacity!==undefined&&(n.shadowOpacity<0||n.shadowOpacity>1)||n.shadowColor!==undefined&&!/^#[0-9a-f]{6}$/i.test(n.shadowColor))throw Error('Invalid shadow styling.');if(n.mesh)mesh(n.mesh);phaseData(n,p);if(n.radius!==undefined&&(!Number.isFinite(n.radius)||n.radius<0))throw Error('Invalid corner radius.');if(n.rawPath&&(typeof n.rawPath!=='string'||n.rawPath.length>1000000))throw Error('Invalid SVG path.');if(typeof n.text!=='string'||typeof n.font!=='string'||!Number.isFinite(n.fontSize)||n.fontSize<=0)throw Error('Invalid text.');for(const [prop,track] of Object.entries(n.tracks||{})){const times=new Set();for(const k of track){if(!validId(k.id)||times.has(k.time)||!['hold','linear','easeIn','easeOut','easeInOut'].includes(k.easing))throw Error('Invalid or duplicate keyframe.');times.add(k.time);if(k.bezier!==undefined&&!validCurve(k.bezier))throw Error('Invalid Bézier tween.');if(prop==='shadowBlur'&&(k.value<0||k.value>200)||prop==='shadowOpacity'&&(k.value<0||k.value>1))throw Error('Invalid shadow keyframe.');if(prop==='mesh')mesh(k.value);else if(prop==='nodes')nodes(k.value);else if(['fill','stroke','shadowColor'].includes(prop)){if(!color(k.value))throw Error('Invalid keyframe colour.');}else if(!Number.isFinite(k.value))throw Error('Invalid numeric keyframe.');}}visit(n.children||[]);});visit(p.layers);if(p.audio){const a=p.audio;for(const key of ['offset','trimStart','trimEnd','volume','duration'])if(!Number.isFinite(a[key]))throw Error('Invalid audio placement.');if(a.offset<0||a.trimStart<0||a.trimEnd<a.trimStart||a.trimEnd>a.duration||a.volume<0||a.volume>2)throw Error('Invalid audio trim.');if(a.clips!==undefined){if(!Array.isArray(a.clips)||a.clips.length>1000)throw Error('Invalid recorded blocks.');const ids=new Set();for(const c of a.clips){if(!validId(c.id)||ids.has(c.id)||typeof c.name!=='string'||![c.offset,c.trimStart,c.trimEnd].every(Number.isFinite)||c.offset<0||c.offset>600||c.trimStart<0||c.trimEnd<=c.trimStart||c.trimEnd>a.duration)throw Error('Invalid recorded block trim.');ids.add(c.id);}}if(!validId(a.assetId))throw Error('Missing audio asset.');}return p;}

function mesh(m){for(const [key,count] of [['rowKnots',m.rows],['colKnots',m.cols]]){const values=m[key];if(values!==undefined&&(!Array.isArray(values)||values.length!==count||values[0]!==0||values.at(-1)!==1||values.some((v,i)=>!Number.isFinite(v)||(i>0&&v<=values[i-1]))))throw Error('Invalid mesh parameter spacing.');}if(m.manualBounds&&(!['x','y','width','height'].every(k=>Number.isFinite(m.manualBounds[k]))||m.manualBounds.width<=0||m.manualBounds.height<=0))throw Error('Invalid manual mesh bounds.');if(!Number.isInteger(m.rows)||!Number.isInteger(m.cols)||m.rows<2||m.cols<2||m.rows>17||m.cols>17||!Array.isArray(m.points)||m.points.length!==m.rows*m.cols||!m.bounds||!['x','y','width','height'].every(k=>Number.isFinite(m.bounds[k]))||m.bounds.width<=0||m.bounds.height<=0||m.points.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y)||!/^#[0-9a-f]{6}$/i.test(p.color)))throw Error('Invalid colour mesh.');}
function png(src){if(typeof src!=='string'||src.length>12*1024*1024||!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(src))throw Error('Invalid embedded PNG image.');}
function phaseData(n,p){if(n.texture){const t=n.texture;png(t.src);if(![t.width,t.height,t.scale,t.x,t.y].every(Number.isFinite)||t.width<=0||t.height<=0||t.width>2048||t.height>2048||t.scale<=0||t.scale>20||!['cover','fit','stretch','tile'].includes(t.mode))throw Error('Invalid image texture.');}if(n.type==='image'&&!n.referenceFrames)png(n.imageSrc);if(n.referenceFrames){const r=n.referenceFrames;if(n.type!=='image'||![r.start,r.duration,r.fps,r.rotation].every(Number.isFinite)||r.start<0||r.duration<=0||r.duration>10||![12,24,25,30,60].includes(r.fps)||!['walk','run','sprint','hop','slide'].includes(r.motion)||!Array.isArray(r.frames)||r.frames.length!==Math.round(r.duration*r.fps)||r.frames.length>600)throw Error('Invalid baked movement reference.');r.frames.forEach(png);if(r.visibleRanges!==undefined&&(!Array.isArray(r.visibleRanges)||r.visibleRanges.some(b=>!Number.isFinite(b.start)||!Number.isFinite(b.end)||b.start<0||b.end<=b.start)))throw Error('Invalid reference range.');}if(n.blocks!==undefined){if(!Array.isArray(n.blocks)||n.blocks.length>1000)throw Error('Invalid animation blocks.');const ids=new Set();for(const b of n.blocks){if(!validId(b.id)||ids.has(b.id)||typeof b.name!=='string'||!Number.isFinite(b.start)||!Number.isFinite(b.end)||b.start<0||b.end<=b.start||b.end>p.duration+.00001||!['animation','reference'].includes(b.kind)||!Array.isArray(b.props)||b.props.some(prop=>!animatable.includes(prop)))throw Error('Invalid animation block range.');ids.add(b.id);if(b.tracks)blockTracks(b.tracks);}}if(n.blockCuts!==undefined){if(!Array.isArray(n.blockCuts)||n.blockCuts.length>1000)throw Error('Invalid snipped ranges.');for(const cut of n.blockCuts){if(!Number.isFinite(cut.start)||!Number.isFinite(cut.end)||cut.start<0||cut.end<=cut.start||cut.end>p.duration+.00001)throw Error('Invalid snipped range.');blockTracks(Object.fromEntries(Object.entries(cut.values).map(([prop,value])=>[prop,[{id:'cut',time:cut.start,value,easing:'hold'}]])));}}}

function blockTracks(tracks){for(const [prop,keys] of Object.entries(tracks)){if(!animatable.includes(prop)||!Array.isArray(keys)||keys.length>40000)throw Error('Invalid block parameter track.');const ids=new Set(),times=new Set();for(const k of keys){if(!validId(k.id)||ids.has(k.id)||!Number.isFinite(k.time)||Math.abs(k.time)>1800||times.has(k.time)||!['hold','linear','easeIn','easeOut','easeInOut'].includes(k.easing)||k.bezier!==undefined&&!validCurve(k.bezier))throw Error('Invalid block keyframe.');ids.add(k.id);times.add(k.time);if(prop==='mesh')mesh(k.value);else if(prop==='nodes')nodes(k.value);else if(['fill','stroke','shadowColor'].includes(prop)){if(!color(k.value))throw Error('Invalid block colour.');}else if(!Number.isFinite(k.value))throw Error('Invalid block value.');}}}
